import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let $a, b, c$ be the distinct positive integers {a}, {b}, and {c}.\nConsider the two sets of integers $A = \\{0, a+b, a+c, b+c\\}$ and $B = \\{a, b, c, a+b+c\\}$.\nLet $S_p(X)$ denote the sum of the $p$-th powers of the elements in a set $X$. It is a known property that $S_1(A) = S_1(B)$ and $S_2(A) = S_2(B)$.\nCompute the value of $S_4(A) - S_4(B)$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
params = rng.sample(range(1, 11), 3)
a, b, c = sorted(params)
return {
    'a': a,
    'b': b,
    'c': c
}

    def verifier(assign):
a = assign['a']
b = assign['b']
c = assign['c']

# Validate constraints
if not (isinstance(a, int) and isinstance(b, int) and isinstance(c, int)):
    return False, None # Must be integers
if not (a > 0 and b > 0 and c > 0):
    return False, None # Must be positive
if len({a, b, c}) != 3:
    return False, None # Must be distinct

# To prevent trivial solutions, ensure they are not too small
if a+b+c < 6:
    return False, None # Smallest is 1,2,3

# Direct calculation for verification
A = {0, a + b, a + c, b + c}
B = {a, b, c, a + b + c}

s4_A = sum(x**4 for x in A)
s4_B = sum(x**4 for x in B)

answer = s4_A - s4_B

# Theoretical calculation
# S_4(A) - S_4(B) = -12*a*b*c*(a+b+c)
theoretical_answer = -12 * a * b * c * (a + b + c)

if answer != theoretical_answer:
    # This would indicate a flaw in the derivation, which is unlikely but good practice to check.
    return False, None

return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

